import subprocess

scad_code = """
$fn = 64;

// Test self-supporting double-shear pin joint with cylindrical middle shaft + 45-deg conical axial retention
// Part A (+X side): holds the Pin (anchored on bed z=0, connected by bottom web on +X and top bridge on +X)
// Part B (-X side): holds the Bore (anchored on bed z=0, wraps 360 deg around cylindrical pin)

module pin_solid() {
    // Bottom flange on bed: z=0..1.2 r=4.2, z=1.2..2.6 tapers 4.2 -> 2.8
    cylinder(h=1.21, r=4.2);
    translate([0, 0, 1.2]) cylinder(h=1.41, r1=4.2, r2=2.8);
    // Pure cylindrical pin shaft: z=2.6..13.4, r=2.8
    translate([0, 0, 2.6]) cylinder(h=10.81, r=2.8);
    // Top retaining cone + cap: z=13.4..14.8 tapers 2.8 -> 4.2, z=14.8..18.0 r=4.2
    translate([0, 0, 13.4]) cylinder(h=1.41, r1=2.8, r2=4.2);
    translate([0, 0, 14.8]) cylinder(h=3.2, r=4.2);
}

// Bore cutout inside Part B (gives 0.5mm radial gap on cylinder, 0.5mm normal gap on cones)
module bore_cutout() {
    // At bottom: z=-0.1..1.7 r=4.7, z=1.7..3.1 tapers 4.7 -> 3.3
    translate([0, 0, -0.1]) cylinder(h=1.81, r=4.7);
    translate([0, 0, 1.7]) cylinder(h=1.41, r1=4.7, r2=3.3);
    // Pure cylindrical bore: z=3.1..12.9, r=3.3 (radial clearance = 3.3 - 2.8 = 0.5mm)
    translate([0, 0, 3.1]) cylinder(h=9.81, r=3.3);
    // Top conical bore seat: z=12.9..14.3 tapers 3.3 -> 4.7, above z=14.3 r=4.7
    translate([0, 0, 12.9]) cylinder(h=1.41, r1=3.3, r2=4.7);
    translate([0, 0, 14.3]) cylinder(h=5.0, r=4.7);
}

// Part A (+X)
union() {
    pin_solid();
    // Top bridge connecting pin cap (z=14.8..18) to Part A body (with 45-deg underside ramp)
    hull() {
        translate([0, 0, 14.8]) cylinder(h=3.2, r=4.2);
        translate([7.5, -4.5, 14.8]) cube([4, 9, 3.2]);
        translate([7.5, -4.5, 11.5]) cube([4, 9, 0.1]);
    }
    // Part A main body on +X (outside r=7.0)
    difference() {
        translate([6.5, -6, 0]) cube([10, 12, 18]);
        translate([0, 0, -1]) cylinder(h=20, r=7.0);
    }
}

// Part B (-X)
difference() {
    union() {
        // 360-deg housing around the pin from z=0..14.1, outer radius 6.5
        cylinder(h=14.1, r1=6.5, r2=6.5);
        // Connect to Part B body on -X
        translate([-15, -6, 0]) cube([15, 12, 14.1]);
        translate([-15, -6, 14.1]) hull() {
            cube([6.5, 12, 3.9]);
            translate([0, 0, -3.9]) cube([9.8, 12, 0.1]);
        }
    }
    bore_cutout();
    // Clearance on +X side so Part B outer housing does not touch Part A body
    // Outer radius of Part B is 6.5, Part A inner cylindrical boundary is 7.0 (0.5mm radial gap!)
    // Also above z=14.1, clear for Part A top bridge
    translate([-1, -10, 14.1]) cube([20, 20, 10]);
}
"""
with open("/tmp/test_cone.scad", "w") as f:
    f.write(scad_code)
subprocess.run(["openscad", "-o", "/tmp/test_cone.stl", "/tmp/test_cone.scad"], check=True)
subprocess.run(["prusa-slicer", "--export-gcode", "--load", "/opt/slicer/p1s_pla_0.20mm_autosupport.ini", "--output", "/tmp/test_cone.gcode", "/tmp/test_cone.stl"], check=True)
with open("/tmp/test_cone.gcode") as f:
    g = f.read()
print("Conical-retained cylindrical pin joint support lines:", sum(1 for line in g.splitlines() if "TYPE:Support" in line or "TYPE:Support material" in line))
for t in set(line for line in g.splitlines() if line.startswith(";TYPE:")):
    print(" ", t)
